
CREATE TABLE `mail_sent` (
  `ms_id` int(1) NOT NULL AUTO_INCREMENT,
  `ms_subject` text,
  `ms_text` text,
  `ms_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ms_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;

/*Data for the table `mail_sent` */

/*Table structure for table `mail_templates` */

DROP TABLE IF EXISTS `mail_templates`;

CREATE TABLE `mail_templates` (
  `mt_id` int(11) NOT NULL AUTO_INCREMENT,
  `mt_name` varchar(255) DEFAULT NULL,
  `mt_key` varchar(255) DEFAULT NULL,
  `mt_subject` text,
  `mt_text` text,
  `mt_active` tinyint(1) DEFAULT '0',
  `mt_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`mt_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8;

/*Data for the table `mail_templates` */

insert  into `mail_templates`(`mt_id`,`mt_name`,`mt_key`,`mt_subject`,`mt_text`,`mt_active`,`mt_create_date`) values (1,'Schedule Call with Business Associate','schedulecall',NULL,'Dear <Business Associate>,\r\n\r\nCarosh Compliance Solutions has been retained by <Company> to conduct an audit of their compliance with HIPAA regulations, as amended by the Final Omnibus Rules.  One of the areas covered in the Final Omnibus Rules relates to Business Associates.  As part of our work for <Company>  we are reviewing <Company’s>   Business Associate relationships.  To this end, we would like to schedule a call with you at your earliest possible convenience within the next 2 weeks.  The purpose of this call will be to determine if you are in fact classified correctly as a Business Associate.\r\n\r\nPlease be assured we make every attempt to make this process as painless as possible.  If you have any questions, please do not hesitate to contact me.\r\n\r\nThanks you in advance for your assistance.\r\n\r\nSincerely,\r\n<Consultant Name>\r\n<Consultant Title>\r\n<Consultant phone>\r\n<Consultant email>\r\n\r\nThe Carosh Group\r\nwww.carosh.com\r\n',0,'2014-05-15 16:28:15'),(2,'Invite Business Associate to Assessment','invitetoassessment','Invite to assessment','Templated email copy will be populated, but user will be able to make changes if necessary.\r\n\r\nDear <Business Associate>,\r\n\r\nCarosh Compliance Solutions has been retained by «Company» to conduct an audit of their compliance with HIPAA regulations, as amended by the Final Omnibus Rules. One of the areas covered in the Final Omnibus Rules relates to Business Associates. As part of our work for «Company» we are reviewing «Company»’s Business Associate relationships.\r\n\r\nLogin page: https://hipaa.carosh.com/\r\nUsername: <username>\r\nPassword: <password>\r\n\r\nWe determined that you are classified as a Business Associate, and on behalf of «Company» we will need to conduct additional due diligence on your compliance with the HIPAA Regulations, again as mandated by the Final Omnibus Rules. To help us with this process we would like to have you fill out the attached questionair, and provide us with the following:\r\n\r\n	•	The signature pages of your most recent Security Risk Assessment and Remediation Plan,\r\n	•	The signature page of your HIPAA Master Policy and Procedure Manual, and \r\n	•	A sample of your most recent training logs.\r\n\r\nFinally, subsequent to the due diligence effort, we will need to discuss the changes in the Business Associates Agreement, and execute a new Business Associates Agreement, as mandated by the Final Omnibus Rules, effective as of September 23, 2013.\r\n\r\nOne of our project managers will contact you to set up a time we can meet with you to review the materials and subsequently discuss and execute the revised Business Associate Agreement.\r\n\r\nPlease be assured we make every attempt to make this process as painless as possible. If you have any questions, please do not hesitate to contact me.\r\n\r\nThanks you in advance for your assistance.\r\n\r\nSincerely,\r\n<Consultant Name>\r\n<Consultant Title>\r\n<Consultant phone>\r\n<Consultant email>\r\n\r\nThe Carosh Group',0,'2014-05-15 16:33:04'),(3,'Email Assignee','breachplan',NULL,'Templated email copy will be populated, but user will be able to make changes if necessary.\r\n\r\n<Client Name>\r\n\r\nTarget Date: <Target Date>\r\n\r\nTask: <Task>\r\n\r\nAction Plan: <Action plan>\r\n\r\nSincerely,\r\n<Consultant Name>\r\n<Consultant Title>\r\n<Consultant phone>\r\n<Consultant email>\r\nThe Carosh Group',0,'2014-05-22 13:57:42'),(4,'Email Assignee','remediationplan',NULL,'Templated email copy will be populated, but user will be able to make changes if necessary.\r\n\r\n<Client Name>\r\n\r\nTarget Date: <Target Date>\r\n\r\nTask: <Task>\r\n\r\nAction Plan: <Action plan>\r\n\r\nSincerely,\r\n<Consultant Name>\r\n<Consultant Title>\r\n<Consultant phone>\r\n<Consultant email>\r\nThe Carosh Group',0,'2014-05-22 13:59:08'),(5,'Invite <Client Name> to Assessment','invitetoassessment2','Invite to assessment','Dear <Client Name>,\r\n\r\nThank you for choosing Carosh Compliance Solutions to assist you with your HIPAA Compliance Program.\r\n\r\nTo get started, we ask you to fill out the preliminary company information we discussed in our “Kick-off meeting”.  As I mentioned at that time, the following will give you access to our system  to log on and answer some administrative questions.\r\n\r\nLogin page: https://hipaa.carosh.com/\r\nUsername: <username>\r\nPassword: <password>\r\n\r\nWe understand the questions may be confusing or raise more questions then they answer.  \r\nMost of our clients request some assistance with this task, or have and number of questions.  If you would like us to go through any or all of the questions, please do not hesitate to contact me to set a time to work together on this task.\r\n\r\nThanks you in advance for your assistance.\r\n\r\nSincerely,\r\n<Consultant Name>\r\n<Consultant Title>\r\n<Consultant phone>\r\n<Consultant email>\r\n\r\nThe Carosh Group\r\nwww.carosh.com\r\n',0,'2014-05-29 14:44:03'),(6,NULL,'createuser','New account','Your login: <login><br/>\r\nYour password: <password>',0,'2014-06-02 15:33:56'),(7,NULL,'forgotpassword','New password','Click <link> to change password',0,'2014-06-02 16:00:53');
